INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 7, 'theory', 'Quiz: objects, arrays and collections');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 7, 0, 'What happens to the original after const b = { ...a }; b.inner.x = 5; if inner is a nested object?', '["The original changes too: the nested object is shared by both copies", "Nothing: the copy is fully independent", "A TypeError is thrown", "Only b.inner changes"]', 0, 'The ... operator makes a shallow copy: the reference to inner is copied, not the object itself. A deep copy needs structuredClone.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 7, 1, 'What does [10, 9, 1].sort() equal?', '["[1, 9, 10]", "[10, 9, 1]", "[1, 10, 9]", "[9, 10, 1]"]', 2, 'Without a compare function, elements are converted to strings and compared by code: "1" < "10" < "9". For numbers you need (a, b) => a - b.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 7, 2, 'When is a Map better than a plain object?', '["When the keys are only short strings", "When the data has to be sent over the network as JSON", "Never: an object is always faster", "When you need arbitrary keys (numbers, objects), insertion order and no extra inherited fields"]', 3, 'A Map accepts any keys, remembers insertion order and has no fields like constructor; but JSON.stringify gives {} for a Map.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 7, 3, 'How do you get the array [1, 2, 3] without repeats from [1, 2, 2, 3, 1]?', '["arr.unique()", "[...new Set(arr)]", "arr.filter(Set)", "Object.keys(arr)"]', 1, 'A Set keeps unique values, and the ... operator unpacks it back into an array, preserving the order of first appearance.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 7, 4, 'What happens to the function and undefined fields in JSON.stringify({ f() {}, u: undefined, n: 1 })?', '["They turn into null", "An error is thrown", "They are skipped: the result is {\"n\":1}", "They turn into strings"]', 2, 'Functions, undefined and symbols are skipped in objects (and become null in arrays); NaN and Infinity turn into null.');
